/**
 * Header/footer brand lockup — Figma Frame 5 (185×25).
 * Wordmark + flower in one SVG so baseline alignment stays locked.
 */
export function BrandLogo({
  title = "Christie Yu",
  className,
  ...rest
}: Omit<IconProps, "size">) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 185 25"
      width={185}
      height={25}
      fill="none"
      className={className}
      role="img"
      aria-label={title}
      {...rest}
    >
      <text
        x="0"
        y="18"
        fill="currentColor"
        style={{
          fontFamily:
            "var(--font-tay-dreamboat), 'Times New Roman', Times, serif",
          fontSize: 18,
          fontWeight: 400,
          letterSpacing: "-0.06em",
          textTransform: "uppercase",
        }}
      >
        CHRISTIE YU
      </text>
      <g transform="translate(161 2.5)">
        <path
          fillRule="evenodd"
          clipRule="evenodd"
          d={FLOWER_PATH}
          fill="currentColor"
        />
      </g>
    </svg>
  );
}

/** Brand flower mark alone (20×20). */
export function FlowerIcon(props: IconProps) {
  return (
    <svg {...baseProps({ size: 20, ...props }, "0 0 20 20")}>
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d={FLOWER_PATH}
        fill="currentColor"
      />
    </svg>
  );
}

